DROP TABLE IF EXISTS `vote`;
CREATE TABLE `vote`  (
  `id` int(10) NOT NULL DEFAULT 0,
  `HWID` varchar(48) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `vote` int(10) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`, `HWID`, `vote`) USING BTREE,
  INDEX `Index 2`(`id`, `vote`) USING BTREE,
  INDEX `Index 3`(`id`) USING BTREE,
  INDEX `Index 4`(`HWID`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for vote_system
-- ----------------------------
DROP TABLE IF EXISTS `vote_system`;
CREATE TABLE `vote_system`  (
  `value_type` tinyint(4) NOT NULL DEFAULT 1,
  `value` char(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '0',
  `penalty_time` decimal(20, 0) NULL DEFAULT 0
) ENGINE = MyISAM CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = Fixed;

-- ----------------------------
-- Table structure for weapon
-- ----------------------------
DROP TABLE IF EXISTS `weapon`;
CREATE TABLE `weapon`  (
  `item_id` decimal(11, 0) NOT NULL DEFAULT 0,
  `name` varchar(120) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '0',
  `additionalname` varchar(120) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `bodypart` varchar(15) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'none',
  `crystallizable` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'false',
  `weight` decimal(4, 0) NOT NULL DEFAULT 0,
  `soulshots` decimal(2, 0) NOT NULL DEFAULT 0,
  `spiritshots` decimal(1, 0) NOT NULL DEFAULT 0,
  `material` varchar(11) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'wood',
  `crystal_type` varchar(4) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'none',
  `p_dam` decimal(5, 0) NOT NULL DEFAULT 0,
  `rnd_dam` decimal(2, 0) NOT NULL DEFAULT 0,
  `weaponType` varchar(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'none',
  `critical` decimal(2, 0) NOT NULL DEFAULT 0,
  `hit_modify` decimal(6, 5) NOT NULL DEFAULT 0.00000,
  `avoid_modify` decimal(2, 0) NOT NULL DEFAULT 0,
  `shield_def` decimal(3, 0) NOT NULL DEFAULT 0,
  `shield_def_rate` decimal(2, 0) NOT NULL DEFAULT 0,
  `atk_speed` decimal(3, 0) NOT NULL DEFAULT 0,
  `mp_consume` decimal(2, 0) NOT NULL DEFAULT 0,
  `m_dam` decimal(3, 0) NOT NULL DEFAULT 0,
  `duration` int(3) NOT NULL DEFAULT -1,
  `time` int(4) NOT NULL DEFAULT -1,
  `price` decimal(11, 0) NOT NULL DEFAULT 0,
  `crystal_count` int(4) NOT NULL DEFAULT 0,
  `sellable` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'false',
  `dropable` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'false',
  `destroyable` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'false',
  `tradeable` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'false',
  `depositable` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'false',
  `enchant4_skill_id` decimal(11, 0) NOT NULL DEFAULT 0,
  `enchant4_skill_lvl` decimal(11, 0) NOT NULL DEFAULT 0,
  `onCast_skill_id` decimal(11, 0) NOT NULL DEFAULT 0,
  `onCast_skill_lvl` decimal(11, 0) NOT NULL DEFAULT 0,
  `onCast_skill_chance` decimal(11, 0) NOT NULL DEFAULT 0,
  `onCrit_skill_id` decimal(11, 0) NOT NULL DEFAULT 0,
  `onCrit_skill_lvl` decimal(11, 0) NOT NULL DEFAULT 0,
  `onCrit_skill_chance` decimal(11, 0) NOT NULL DEFAULT 0,
  `change_weaponId` decimal(11, 0) NOT NULL DEFAULT 0,
  `skill` varchar(70) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '0-0;',
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = Dynamic;

